-- name: NextPurchaseNumber :one
-- Row-locking increment, same pattern as sales.next_sale_number (D-45):
-- the UPDATE itself takes the row lock, so no separate SELECT ... FOR
-- UPDATE is needed. Returns the number this purchase should use (before
-- the increment); the service formats it as "P-%06d" (D-45) and passes
-- the formatted text into CreatePurchase.
UPDATE shops
SET next_purchase_number = next_purchase_number + 1
WHERE id = $1
RETURNING (next_purchase_number - 1)::bigint;

-- name: CreatePurchase :one
-- number is always server-generated by the service from
-- NextPurchaseNumber, never client-supplied (D-45, hard rule 8).
INSERT INTO purchases (
    id, shop_id, supplier_id, location_id, number,
    supplier_invoice_no, note, created_by
)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
RETURNING *;

-- name: CreatePurchaseItem :one
INSERT INTO purchase_items (id, shop_id, purchase_id, variant_id, qty, unit_cost, line_total)
VALUES ($1, $2, $3, $4, $5, $6, $7)
RETURNING *;

-- name: ListPurchaseItems :many
-- `, id` tiebreaker for determinism, same reasoning as
-- ListVariantsForStaff (created_at alone can tie within one transaction).
SELECT * FROM purchase_items
WHERE shop_id = $1 AND purchase_id = $2
ORDER BY created_at, id;

-- name: DeletePurchaseItems :execrows
-- Join rows, hard-deleted (§ 04-DATA-MODEL.md rule 7); used by the service
-- to replace a draft's item list (delete then re-CreatePurchaseItem). The
-- USING join guards status = 'draft' at the SQL level too (defense in
-- depth alongside the service's own GetPurchaseForUpdate check): on a
-- received/cancelled purchase this affects 0 rows, same signal shape as
-- UpdatePurchaseHeader/SetPurchaseReceived/SetPurchaseCancelled. The
-- affected-row count is not on its own a reliable "was it draft" check —
-- a draft with no items yet also affects 0 rows — the service still reads
-- status from GetPurchaseForUpdate first.
DELETE FROM purchase_items
USING purchases
WHERE purchase_items.purchase_id = purchases.id
    AND purchase_items.shop_id = $1
    AND purchase_items.purchase_id = $2
    AND purchases.status = 'draft';

-- name: GetPurchase :one
SELECT * FROM purchases
WHERE shop_id = $1 AND id = $2;

-- name: GetPurchaseForUpdate :one
-- Locks the header row before a draft-only mutation (update header,
-- replace items, receive, cancel) so two concurrent requests cannot both
-- observe status = 'draft' and race past each other.
SELECT * FROM purchases
WHERE shop_id = $1 AND id = $2
FOR UPDATE;

-- name: ListPurchases :many
-- Keyset pagination on (created_at, id), newest first. status/supplier_id
-- are optional exact-match filters (sqlc.narg).
SELECT * FROM purchases
WHERE shop_id = sqlc.arg('shop_id')
    AND (sqlc.narg('status')::purchase_status IS NULL OR status = sqlc.narg('status'))
    AND (sqlc.narg('supplier_id')::uuid IS NULL OR supplier_id = sqlc.narg('supplier_id'))
    AND (
        sqlc.narg('cursor_created_at')::timestamptz IS NULL
        OR (created_at, id) < (sqlc.narg('cursor_created_at')::timestamptz, sqlc.narg('cursor_id')::uuid)
    )
ORDER BY created_at DESC, id DESC
LIMIT sqlc.arg('limit');

-- name: UpdatePurchaseHeader :one
-- Patch, allowed only while status = 'draft' (the WHERE clause is the
-- enforcement; the service maps zero rows returned to
-- PURCHASE_NOT_DRAFT/NOT_FOUND). supplier_invoice_no/note are nullable
-- (D-35): explicit clear flags, same shape as UpdateSupplier.
UPDATE purchases
SET
    supplier_id = COALESCE(sqlc.narg('supplier_id'), supplier_id),
    location_id = COALESCE(sqlc.narg('location_id'), location_id),
    supplier_invoice_no = CASE WHEN sqlc.arg('clear_supplier_invoice_no')::bool THEN NULL ELSE COALESCE(sqlc.narg('supplier_invoice_no'), supplier_invoice_no) END,
    note = CASE WHEN sqlc.arg('clear_note')::bool THEN NULL ELSE COALESCE(sqlc.narg('note'), note) END,
    updated_at = now()
WHERE shop_id = sqlc.arg('shop_id') AND id = sqlc.arg('id') AND status = 'draft'
RETURNING *;

-- name: SetPurchaseReceived :one
-- Only a 'draft' purchase can be received; the WHERE clause is the guard,
-- same PURCHASE_NOT_DRAFT/PURCHASE_ALREADY_RECEIVED mapping as
-- UpdatePurchaseHeader. total_cost is computed server-side from the items
-- (never trust a client value, hard rule 8).
UPDATE purchases
SET status = 'received', received_at = now(), total_cost = $3, updated_at = now()
WHERE shop_id = $1 AND id = $2 AND status = 'draft'
RETURNING *;

-- name: ListPurchaseItemsWithLabels :many
-- Joins each purchase_items row to its variant and product for the
-- response-only productName/variantLabel/sku fields
-- (contracts/openapi.yaml's PurchaseItem, T4): variantLabel itself is
-- built in Go from variant_sku/variant_attributes plus
-- attribute_definitions' sort order (mirrors
-- admin/src/catalog/variants.ts's own variantLabel), not computed in SQL.
-- productName uses the same locale-fallback (requested -> 'uz' -> any,
-- ADR-012) as ListProductsForStaff. v.shop_id/p.shop_id are joined
-- explicitly, not just pi.shop_id, so a row can never resolve through
-- another shop's variant/product even though every id here was already
-- validated at CreatePurchase time (hard rule 1, defense in depth).
SELECT
    pi.id, pi.purchase_id, pi.variant_id, pi.qty, pi.unit_cost, pi.line_total, pi.created_at,
    v.sku AS variant_sku,
    v.attributes AS variant_attributes,
    COALESCE(t.locale, '') AS locale_used,
    COALESCE(t.name, '') AS product_name
FROM purchase_items pi
JOIN product_variants v ON v.id = pi.variant_id AND v.shop_id = pi.shop_id
JOIN products p ON p.id = v.product_id AND p.shop_id = pi.shop_id
LEFT JOIN LATERAL (
    SELECT pt.locale, pt.name
    FROM product_translations pt
    WHERE pt.product_id = p.id
    ORDER BY
        CASE
            WHEN pt.locale = sqlc.arg('locale') THEN 0
            WHEN pt.locale = 'uz' THEN 1
            ELSE 2
        END
    LIMIT 1
) t ON true
WHERE pi.shop_id = sqlc.arg('shop_id') AND pi.purchase_id = sqlc.arg('purchase_id')
ORDER BY pi.created_at, pi.id;

-- name: SetPurchaseCancelled :one
-- Cancellable from 'draft' or 'received'; not from 'cancelled' again (the
-- WHERE clause maps a second cancel to PURCHASE_ALREADY_CANCELLED in the
-- service). Cancelling a 'received' purchase's reversing stock movements
-- are written separately by stock.Service.Move before/after this call in
-- the same transaction.
UPDATE purchases
SET status = 'cancelled', cancelled_at = now(), updated_at = now()
WHERE shop_id = $1 AND id = $2 AND status <> 'cancelled'
RETURNING *;
